// post segment along +x, cross-section (y width) x (z height) rounded, bottom flat-ish on bed
module post_seg(x0, x1, w, h, r) {
    hull() for (yy = [-(w/2 - r), w/2 - r], zz = [r, h - r])
        translate([x0, yy, zz]) rotate([0, 90, 0]) cylinder(h = x1 - x0, r = r);
}

arguments.new:
// post cross-section: flat bottom on the bed, vertical sides, rounded top
module post_profile(w, h, r) {
    hull() {
        polygon(points = [[0, -w/2], [0, w/2], [-(h-r), w/2], [-(h-r), -w/2]]);
        translate([-(h-r), -(w/2-r)]) circle(r = r);
        translate([-(h-r), (w/2-r)]) circle(r = r);
    }
}
module post_seg(x0, x1, w, h, r) {
    translate([x0, 0, 0]) rotate([0, 90, 0])
        linear_extrude(x1 - x0) post_profile(w, h, r);
}
